import {CalendarRange, IndexPath} from '@ui-kitten/components';
import {create} from 'zustand';
import {
  IReceiptItem,
  TypeReceipt,
} from '../../../../model/interface/receipt.interface';
import {TYPE_REQUEST_FLOW} from '../../../../model/type/status';

export type ValueFilterSearch = {
  rangeDay?: CalendarRange<Date>;
  paymentMethod?: IndexPath[];
  requestStatus?: IndexPath[];
  status?: IndexPath[];
  type?: IndexPath[];
};

interface ZutandStore {
  listTypeReceipt: {label: string; value: string}[];
  setListTypeReceipt: (
    listTypeReceipt: {label: string; value: string}[],
  ) => void;
}

const initialReceiptState = {
  listTypeReceipt: [],
};

export const useReceiptZustandStore = create<ZutandStore>((set, get) => ({
  ...initialReceiptState,
  setListTypeReceipt: (listTypeReceipt: {label: string; value: string}[]) => {
    set({listTypeReceipt});
  },
}));
