import React, {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {RefreshControl, ScrollView, View} from 'react-native';
import {SafeAreaView} from 'react-native-safe-area-context';
import Body from './components/Body';
import Header from './components/Header';
import OverviewDocument from './components/OverviewDocument';
import Statistical from './components/Statistical';
import styles from './styles';
import {useAccountInfoServices} from '../../../hooks/apiHooks/useAccountInfoServices';
import {useReceiptServices} from '../../../hooks/apiHooks/useAPI';

export interface INumberReceipt {
  numberReceipt: number;
  numberNumberingReceipt: number;
  numberReceiptProcessing: number;
  numberReceiptReleased: number;
  numberReceiptFundSubmited: number;
  numberReceiptPendingFundSubmited: number;
}

const Home = () => {
  const {t} = useTranslation();
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [numberReceipt, setNumberReceipt] = useState<INumberReceipt>({
    numberReceipt: 0,
    numberNumberingReceipt: 0,
    numberReceiptProcessing: 0,
    numberReceiptReleased: 0,
    numberReceiptFundSubmited: 0,
    numberReceiptPendingFundSubmited: 0,
  });
  const AccountServices = useAccountInfoServices();
  const ReceiptService = useReceiptServices();

  useEffect(() => {
    handleInitData();
    // AccountServices.loginMiniApp();
  }, []);

  const onRefreshData = () => {
    setIsRefreshing(true);
    handleInitData();
  };

  const getDashboardReport = async () => {
    const data = await ReceiptService.getDashboardReport();
    return data;
  };

  const getNumberReceipt = async () => {
    const data = await ReceiptService.getReceipt(0, 1);
    return data?.totalData;
  };

  const getNumberReceiptFundSubmited = async () => {
    const body = {
      q: '',
      terms: {
        requestStatus: ['fund_submitted'],
      },
    };
    const data = await ReceiptService.getReceipt(0, 1, body);
    return data?.totalData;
  };

  const getNumberReceiptPendingFundSubmited = async () => {
    const body = {
      q: '',
      terms: {
        requestStatus: ['pending_fund_submission'],
      },
    };
    const data = await ReceiptService.getReceipt(0, 1, body);
    return data?.totalData;
  };

  const handleInitData = async () => {
    try {
      const [
        numberReceipt,
        numberReceiptFundSubmited,
        numberReceiptPendingFundSubmited,
        dashboardReport,
      ] = await Promise.all([
        getNumberReceipt(),
        getNumberReceiptFundSubmited(),
        getNumberReceiptPendingFundSubmited(),
        getDashboardReport(),
      ]);

      setNumberReceipt({
        numberReceipt: numberReceipt || 0,
        numberNumberingReceipt: dashboardReport?.['error_receipt'] || 0,
        numberReceiptProcessing: dashboardReport?.['processing_receipt'] || 0,
        numberReceiptReleased: dashboardReport?.['released_receipt'] || 0,
        numberReceiptFundSubmited: numberReceiptFundSubmited || 0,
        numberReceiptPendingFundSubmited: numberReceiptPendingFundSubmited || 0,
      });
    } catch (error) {
    } finally {
      setIsRefreshing(false);
    }
  };

  return (
    <SafeAreaView edges={[]} style={styles.ctnMain}>
      <Header />
      <ScrollView
        style={styles.mainContainer}
        showsVerticalScrollIndicator={false}
        refreshControl={
          <RefreshControl refreshing={isRefreshing} onRefresh={onRefreshData} />
        }>
        <View style={styles.body}>
          <Body />
          <OverviewDocument numberReceipt={numberReceipt} />
          <Statistical numberReceipt={numberReceipt} />
        </View>
      </ScrollView>
    </SafeAreaView>
  );
};

export default Home;
